/**
 ******************************************************************************
 * @file    app_rtos.c
 * TEAM CODE (integration: Brendon) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   Creates every shared RTOS object declared in app_rtos.h.
 *
 * RTOS role: no task of its own. App_RTOS_Init() runs once in main() after
 * osKernelInitialize() and before the generated osThreadNew() calls; every
 * handle is checked non-NULL, so a heap shortfall stops the board at boot
 * (Error_Handler: the splash stays, and g_rtos_create_failed names the
 * object in the debugger) instead of crashing later on a NULL queue.
 *
 * Steps in App_RTOS_Init(), in order:
 *   1. the control queues (commands, requests, status);
 *   2. the bulk audio objects (pcmFrameQueue, audioBlockPool, audioBlockQueue);
 *   3. faultBeepSem, faultQueue and the two debug-screen queues;
 *   4. the effect-file objects (fxRenderReqQueue, fxRenderReplyQueue,
 *      fxChunkPool) and the sixth task, FxRenderTask. CubeMX does not know
 *      this task, so it is created here, with static memory and the lowest
 *      priority a task can have.
 * (The log and console queues went with the serial console on 1 Nov 2026.)
 *
 * The two bulk audio objects (pcmFrameQueue, audioBlockPool) use STATIC
 * memory (configSUPPORT_STATIC_ALLOCATION == 1) so their ~15 KB lives in
 * .bss and does not compete with the five CubeMX task stacks for the 28 KB
 * RTOS heap.
 * The effect-file objects and FxRenderTask's stack are static too, so the
 * new task takes nothing from that heap.
 * Words: .bss = the RAM for static variables, reserved once by the linker;
 * RTOS heap = ucHeap (configTOTAL_HEAP_SIZE, 28 KB), where osMessageQueueNew
 * and osThreadNew take their memory when they are not given any.
 * Slide numbers refer to ZEIT4230 lecture 07.
 ******************************************************************************/
#include "app_rtos.h"
#include "main.h"
#include "FreeRTOS.h"           /* StaticQueue_t only (static-allocation control block type) */
#include "freertos_mpool.h"     /* MEMPOOL_ARR_SIZE / StaticMemPool_t for the static pool */
#include <stddef.h>             /* offsetof, for the size checks below */
#include <string.h>

/* --------------------- message sizes (the contract) ----------------------
 * The RAM budget and the "new field sits in old padding" layouts of
 * app_rtos.h rely on these sizes, so the build stops if a field is added by
 * mistake instead of every queue silently growing. Checked on the target
 * only: GCC for ARM stores an enum in the smallest integer type that holds
 * it (one byte here), a PC compiler uses four bytes. */
#ifdef __arm__
_Static_assert(sizeof(JackCmd_t) == 24U, "JackCmd_t is 24 bytes");
_Static_assert(offsetof(JackCmd_t, seq) == 19U, "JackCmd_t.seq sits in what was padding");
_Static_assert(sizeof(JackReply_t) == 4U, "JackReply_t is 4 bytes");
_Static_assert(offsetof(JackReply_t, seq) == 3U, "JackReply_t.seq is its last byte");
_Static_assert(sizeof(StorageStatusMsg_t) == 72U, "StorageStatusMsg_t is 72 bytes");
_Static_assert(offsetof(StorageStatusMsg_t, cmd_seq) == 61U, "cmd_seq sits in what was padding");
_Static_assert(offsetof(StorageStatusMsg_t, cmd_ok) == 62U, "cmd_ok sits in what was padding");
_Static_assert(offsetof(StorageStatusMsg_t, cmd_detail) == 63U, "cmd_detail sits in what was padding");
_Static_assert(sizeof(StorageReq_t) == 24U, "StorageReq_t is 24 bytes");
_Static_assert(sizeof(StorageReply_t) == 292U, "StorageReply_t is 292 bytes");
_Static_assert(sizeof(FxRenderReq_t) == 12U, "FxRenderReq_t is 12 bytes");
_Static_assert(sizeof(FxRenderReply_t) == 12U, "FxRenderReply_t is 12 bytes");
_Static_assert(sizeof(FxChunk_t) == 2604U, "FxChunk_t is 2604 bytes (in, out and the 44-byte carry)");
_Static_assert(FX_RENDER_CHUNK_OUT == (FX_RENDER_CHUNK_IN * 3U) / 2U,
               "a 32 kHz chunk becomes 3/2 as many samples at 48 kHz");
_Static_assert((FX_RENDER_CHUNK_IN % AUDIO_BLOCK_SAMPLES) == 0U,
               "a chunk is a whole number of 64-sample blocks");
#endif

/* ----------------------------- shared handles ---------------------------- */
osMessageQueueId_t jackCmdQueue       = NULL;
osMessageQueueId_t tomCmdQueue        = NULL;
osMessageQueueId_t storageReqQueue    = NULL;
osMessageQueueId_t batteryQueue       = NULL;
osMessageQueueId_t storageStatusQueue = NULL;
osMessageQueueId_t pcmFrameQueue      = NULL;
osMessageQueueId_t audioBlockQueue    = NULL;
osMemoryPoolId_t   audioBlockPool     = NULL;
osSemaphoreId_t    faultBeepSem       = NULL;
osMessageQueueId_t faultQueue         = NULL;
osMessageQueueId_t brendonCmdQueue    = NULL;
osMessageQueueId_t powerDebugQueue    = NULL;
osMessageQueueId_t fxRenderReqQueue   = NULL;
osMessageQueueId_t fxRenderReplyQueue = NULL;
osThreadId_t       FxRenderTaskHandle = NULL;
osMemoryPoolId_t   fxChunkPool        = NULL;

volatile uint8_t   g_msc_media_ready  = 0U;
AppRtosDropped_t   g_rtos_dropped;

/* Name of the RTOS object that could not be created at boot (NULL = all
 * were). Read it in the debugger (Live Expressions / Watch) after the board
 * halts in Error_Handler(), like g_stack_overflow_task in freertos.c. */
volatile const char *g_rtos_create_failed = NULL;

/* ----------------------------- static storage ---------------------------- */
/* pcmFrameQueue: 200 x 64 B = 12.8 KB (>= 200 ms of SD stall, see docs). */
static PcmFrame_t    s_pcm_frame_storage[PCM_FRAME_QUEUE_LEN];
static StaticQueue_t s_pcm_frame_cb;

/* audioBlockPool: 16 x sizeof(AudioBlock_t) rounded to 4 = 2.1 KB. */
static uint32_t        s_audio_pool_storage[MEMPOOL_ARR_SIZE(AUDIO_POOL_BLOCKS, sizeof(AudioBlock_t)) / 4U];
static StaticMemPool_t s_audio_pool_cb;

/* Effect files: the two render queues and FxRenderTask, all static, so the
 * new task costs the RTOS heap (whose headroom was never measured) nothing
 * (RAM budget: docs/RTOS_ARCHITECTURE.md section 4). */
static FxRenderReq_t   s_fx_req_storage[FX_RENDER_QUEUE_LEN];
static StaticQueue_t   s_fx_req_cb;
static FxRenderReply_t s_fx_rep_storage[FX_RENDER_QUEUE_LEN];
static StaticQueue_t   s_fx_rep_cb;
static StaticTask_t    s_fx_task_cb;
static uint64_t        s_fx_task_stack[FX_RENDER_STACK_BYTES / sizeof(uint64_t)];   /* 8-byte aligned */
/* fxChunkPool: ONE FxChunk_t (2.6 KB). Jack allocates it before each request
 * and frees it when the reply (also a late one) has been read; FxRenderTask
 * only uses the pointer it was sent (slide 31, as audioBlockPool). */
static uint32_t        s_fx_chunk_storage[MEMPOOL_ARR_SIZE(FX_CHUNK_POOL_BLOCKS, sizeof(FxChunk_t)) / 4U];
static StaticMemPool_t s_fx_chunk_cb;

/* ------------------------------ helpers ---------------------------------- */
/* Used by tasks and by ISRs (from an ISR the timeout must be 0: an interrupt
 * cannot wait). msg is copied into the queue, so the caller may reuse it. */
osStatus_t App_RTOS_Put(osMessageQueueId_t q, const void *msg, uint32_t timeout,
                        volatile uint32_t *dropped)
{
    osStatus_t st = osMessageQueuePut(q, msg, 0U, timeout);
    if (st != osOK && dropped != NULL) {
        (*dropped)++;               /* queue-full policy, slide 18: count and move on */
    }
    return st;
}

/* "Newest wins" for a 1-deep status queue: empty it, then put the new
 * snapshot, so the reader always gets the latest state and never an old
 * one. Reset and put are two steps; each of these queues (batteryQueue,
 * storageStatusQueue, powerDebugQueue) has one producer task, so nothing can
 * slip in between. */
void App_RTOS_Publish(osMessageQueueId_t q, const void *msg, volatile uint32_t *dropped)
{
    (void)osMessageQueueReset(q);   /* length-1 queue: newest wins */
    (void)App_RTOS_Put(q, msg, 0U, dropped);
}

void App_RTOS_RaiseFault(uint8_t source, uint8_t code, const char *line2, const char *line3)
{
    FaultMsg_t m;
    memset(&m, 0, sizeof(m));       /* both lines end NUL-terminated even when cut */
    m.source = source;
    m.code   = code;
    if (line2 != NULL) strncpy(m.line2, line2, sizeof(m.line2) - 1U);
    if (line3 != NULL) strncpy(m.line3, line3, sizeof(m.line3) - 1U);
    /* Timeout 0: the producers (the audio, storage and battery/USB code, and
     * the debug screen's test fault) must never wait for the UI. Four pending
     * faults is plenty; a fifth is counted. */
    (void)App_RTOS_Put(faultQueue, &m, 0U, &g_rtos_dropped.fault);
}

/* A NULL handle at boot means the RTOS heap is too small or a size is wrong:
 * stop at once (Error_Handler() in main.c disables interrupts and loops for
 * ever) rather than crash later on a NULL queue. The screen is not running
 * yet, so the object's name goes into g_rtos_create_failed for the debugger.
 * The usual fix is a bigger TOTAL_HEAP_SIZE in CubeMX (FREERTOS). */
static void check(const char *what, const void *handle)
{
    if (handle == NULL) {
        g_rtos_create_failed = what;
        Error_Handler();
    }
}

/* ------------------------------- init ------------------------------------ */
void App_RTOS_Init(void)
{
    memset(&g_rtos_dropped, 0, sizeof(g_rtos_dropped));

    /* Control queues (slide 16): fixed-size structs/enums, heap-allocated. */
    const osMessageQueueAttr_t jackAttr = { .name = "jackCmd" };
    jackCmdQueue = osMessageQueueNew(JACK_CMD_QUEUE_LEN, sizeof(JackCmd_t), &jackAttr);
    check("jackCmdQueue", jackCmdQueue);

    const osMessageQueueAttr_t tomAttr = { .name = "tomCmd" };
    tomCmdQueue = osMessageQueueNew(TOM_CMD_QUEUE_LEN, sizeof(TomCmd_t), &tomAttr);
    check("tomCmdQueue", tomCmdQueue);

    const osMessageQueueAttr_t reqAttr = { .name = "storageReq" };
    storageReqQueue = osMessageQueueNew(STORAGE_REQ_QUEUE_LEN, sizeof(StorageReq_t), &reqAttr);
    check("storageReqQueue", storageReqQueue);

    const osMessageQueueAttr_t batAttr = { .name = "battery" };
    batteryQueue = osMessageQueueNew(1U, sizeof(BatteryMsg_t), &batAttr);
    check("batteryQueue", batteryQueue);

    const osMessageQueueAttr_t stAttr = { .name = "storageStatus" };
    storageStatusQueue = osMessageQueueNew(1U, sizeof(StorageStatusMsg_t), &stAttr);
    check("storageStatusQueue", storageStatusQueue);

    /* Bulk audio path (slides 29-31 + slide 36): static storage. */
    const osMessageQueueAttr_t pcmAttr = {
        .name    = "pcmFrame",
        .cb_mem  = &s_pcm_frame_cb,
        .cb_size = sizeof(s_pcm_frame_cb),
        .mq_mem  = s_pcm_frame_storage,
        .mq_size = sizeof(s_pcm_frame_storage),
    };
    pcmFrameQueue = osMessageQueueNew(PCM_FRAME_QUEUE_LEN, sizeof(PcmFrame_t), &pcmAttr);
    check("pcmFrameQueue", pcmFrameQueue);

    const osMemoryPoolAttr_t poolAttr = {
        .name    = "audioBlocks",
        .cb_mem  = &s_audio_pool_cb,
        .cb_size = sizeof(s_audio_pool_cb),
        .mp_mem  = s_audio_pool_storage,
        .mp_size = sizeof(s_audio_pool_storage),
    };
    audioBlockPool = osMemoryPoolNew(AUDIO_POOL_BLOCKS, sizeof(AudioBlock_t), &poolAttr);
    check("audioBlockPool", audioBlockPool);

    /* Pointer queue, same length as the pool so a put can never block for space. */
    const osMessageQueueAttr_t blkAttr = { .name = "audioBlocks" };
    audioBlockQueue = osMessageQueueNew(AUDIO_POOL_BLOCKS, sizeof(AudioBlock_t *), &blkAttr);
    check("audioBlockQueue", audioBlockQueue);

    /* Counting semaphore for "this happened N times" events (slide 12). */
    const osSemaphoreAttr_t semAttr = { .name = "faultBeep" };
    faultBeepSem = osSemaphoreNew(FAULT_BEEP_MAX_PENDING, 0U, &semAttr);
    check("faultBeepSem", faultBeepSem);

    /* Fault screen messages (4 x 44 B, ~0.26 KB of RTOS heap with its
     * control block): every task -> TonyTask. */
    const osMessageQueueAttr_t faultAttr = { .name = "fault" };
    faultQueue = osMessageQueueNew(FAULT_QUEUE_LEN, sizeof(FaultMsg_t), &faultAttr);
    check("faultQueue", faultQueue);

    /* Debug screen (4 x 4 B commands to BrendonTask, one 26 B power snapshot
     * back; ~0.2 KB of RTOS heap with their control blocks). */
    const osMessageQueueAttr_t bcmdAttr = { .name = "brendonCmd" };
    brendonCmdQueue = osMessageQueueNew(BRENDON_CMD_QUEUE_LEN, sizeof(BrendonCmd_t), &bcmdAttr);
    check("brendonCmdQueue", brendonCmdQueue);

    const osMessageQueueAttr_t pdbgAttr = { .name = "powerDebug" };
    powerDebugQueue = osMessageQueueNew(1U, sizeof(PowerDebugMsg_t), &pdbgAttr);
    check("powerDebugQueue", powerDebugQueue);

    /* Effect files: JackStorageTask <-> FxRenderTask (the messages and the
     * chunk hand-over are explained next to FxChunk_t in app_rtos.h). */
    const osMessageQueueAttr_t fxqAttr = {
        .name    = "fxRenderReq",
        .cb_mem  = &s_fx_req_cb,
        .cb_size = sizeof(s_fx_req_cb),
        .mq_mem  = s_fx_req_storage,
        .mq_size = sizeof(s_fx_req_storage),
    };
    fxRenderReqQueue = osMessageQueueNew(FX_RENDER_QUEUE_LEN, sizeof(FxRenderReq_t), &fxqAttr);
    check("fxRenderReqQueue", fxRenderReqQueue);

    const osMessageQueueAttr_t fxrAttr = {
        .name    = "fxRenderReply",
        .cb_mem  = &s_fx_rep_cb,
        .cb_size = sizeof(s_fx_rep_cb),
        .mq_mem  = s_fx_rep_storage,
        .mq_size = sizeof(s_fx_rep_storage),
    };
    fxRenderReplyQueue = osMessageQueueNew(FX_RENDER_QUEUE_LEN, sizeof(FxRenderReply_t), &fxrAttr);
    check("fxRenderReplyQueue", fxRenderReplyQueue);

    const osMemoryPoolAttr_t fxcAttr = {
        .name    = "fxChunk",
        .cb_mem  = &s_fx_chunk_cb,
        .cb_size = sizeof(s_fx_chunk_cb),
        .mp_mem  = s_fx_chunk_storage,
        .mp_size = sizeof(s_fx_chunk_storage),
    };
    fxChunkPool = osMemoryPoolNew(FX_CHUNK_POOL_BLOCKS, sizeof(FxChunk_t), &fxcAttr);
    check("fxChunkPool", fxChunkPool);

    /* FxRenderTask makes the effect files for JackStorageTask.
     * Its priority, osPriorityIdle (FreeRTOS 1, just above the kernel's own
     * idle task), is below every other task: it only uses the CPU time all
     * of them leave, so it can never slow the screen or the audio down.
     * While an effect file is being made, the kernel's own idle task (0)
     * therefore gets almost no time. That is safe here: no task is ever
     * deleted (a task that deletes itself is freed by the idle task), there
     * is no idle hook (configUSE_IDLE_HOOK 0 in FreeRTOSConfig.h) and no
     * tickless low-power sleep (configUSE_TICKLESS_IDLE is not set, so
     * FreeRTOS.h makes it 0).
     * The kernel is initialised but not started yet, so creating a task
     * here, before the five generated osThreadNew() calls, is allowed. */
    const osThreadAttr_t fxtAttr = {
        .name       = "FxRenderTask",
        .cb_mem     = &s_fx_task_cb,
        .cb_size    = sizeof(s_fx_task_cb),
        .stack_mem  = s_fx_task_stack,
        .stack_size = sizeof(s_fx_task_stack),
        .priority   = FX_RENDER_PRIORITY,
    };
    FxRenderTaskHandle = osThreadNew(TomFx_TaskEntry, NULL, &fxtAttr);
    check("FxRenderTask", FxRenderTaskHandle);

    g_msc_media_ready = 0U;
}

/* --------------------------- diagnostics --------------------------------- */
static const char *const s_task_names[APP_RTOS_TASK_COUNT] = {
    "JackAudioTask", "TomTask", "JackStorageTask", "BrendonTask", "TonyTask", "FxRenderTask" };

const char *App_RTOS_TaskName(uint32_t i)
{
    return (i < APP_RTOS_TASK_COUNT) ? s_task_names[i] : "?";
}

const char *App_RTOS_BuildString(void)
{
    return __DATE__ " " __TIME__;
}

void App_RTOS_GetStats(AppRtosStats_t *out)
{
    if (out == NULL) return;
    /* Same order as s_task_names. The handles are written by main() before the
     * kernel starts, so reading them here needs no lock. */
    const osThreadId_t tasks[APP_RTOS_TASK_COUNT] = {
        JackAudioTaskHandle, TomTaskHandle, JackStorageTaskHandle,
        BrendonTaskHandle, TonyTaskHandle, FxRenderTaskHandle };

    out->uptime_ms = osKernelGetTickCount();          /* configTICK_RATE_HZ = 1000: one tick per ms */
    /* Diagnostic-only exception to the "CMSIS-RTOS v2 API only" rule: there is
     * no CMSIS call that reports heap headroom, and the RAM budget in
     * docs/RTOS_ARCHITECTURE.md needs it. */
    out->heap_free     = (uint32_t)xPortGetFreeHeapSize();
    out->heap_min_free = (uint32_t)xPortGetMinimumEverFreeHeapSize();
    out->heap_total    = (uint32_t)configTOTAL_HEAP_SIZE;
    out->dropped       = g_rtos_dropped;
    out->jack_missed   = Jack_GetDeadlineMissed();
    out->tom_missed    = Tom_GetDeadlineMissed();
    out->tom_underruns = Tom_GetUnderruns();
    for (uint32_t i = 0U; i < APP_RTOS_TASK_COUNT; i++) {
        /* osThreadGetStackSpace = uxTaskGetStackHighWaterMark in bytes: the
         * "high-water mark", the least free stack the task has ever had
         * (FreeRTOS counts how much of the 0xA5 fill at the stack's end is
         * still untouched) */
        out->stack_free[i] = (tasks[i] != NULL) ? (uint32_t)osThreadGetStackSpace(tasks[i])
                                                : APP_RTOS_STACK_UNKNOWN;
    }
}
